INSERT INTO monster VALUES (657,'Blue','Blue, 1st-Level Psion (Telepath)',NULL,'Small','Humanoid','Goblinoid, Psionic','1d4+1 plus 4 (10 hp)','+1','30 ft. (6 squares)','16 (+1 size, +1 Dex, +4 inertial armor), touch 12, flat-footed 15','+0','-6','Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)','Quarterstaff -2 melee (1d4-2) or light crossbow +1 ranged (1d6/19-20)','5 ft.','5 ft.','Psionic powers','Darkvision 60 ft.','Fort +2, Ref +0, Will +3','Str 6, Dex 13, Con 14, Int 17, Wis 12, Cha 8','Concentration +6, Hide +7, Move Silently +5, Psicraft +7, Ride +5, Spot +3','Psionic Dodge','Psionic Body',NULL,'Temperate plains','Solitary, gang (1 plus 4-9 goblin warriors), band (2d10 plus 10-100 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level), warband (2d4 plus 10-24 goblin warriors with worg mounts), or tribe (4d10 plus 40-400 goblin warriors plus 100% noncombatants plus 1 3rd-level sergeant per 20 adults, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 10-24 worgs, and 2-4 dire wolves)','1','Standard','Usually neutral evil','By character class (usually psion)','+1','','1st-level psion (telepath) blue; CR 1; Small humanoid (goblinoid, psionic); HD 1d4+1 plus 4; hp 10; Init +1; Spd 30 ft. (6 squares); AC 16 (+1 size, +1 dex, +4 inertial armor), touch 12, flat-footed 15; Base Atk +0; Grp -6; Atk -2 melee (1d4-2, quarterstaff) or +1 ranged (1d6/19-20, light crossbow); Full Atk -2 melee (1d4-2, quarterstaff) or +1 ranged (1d6/19-20, light crossbow); Space/Reach 5 ft./5 ft.; SA Psionic powers; SQ Darkvision 60 ft.; AL NE; SV Fort +2, Ref +0, Will +3; Str 6, Dex 13, Con 14, Int 17, Wis 12, Cha 8\n\nSkills and Feats: Concentration +6, Hide +7, Move Silently +5, Psicraft +7, Ride +5, Spot +3; Psionic Body, Psionic Dodge','\n      <div topic=\"Blue\" level=\"2\"><p><h2>Blue</h2></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"